import{_ as l,a0 as p,w as d,s as c,ao as t,I as i,x as n,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"chown 命令简介 | LCTT x X-CMD","titleTemplate":false,"description":"chown 命令简介 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"chown 命令简介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"chown 命令简介 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190826 Introduction to the Linux chown command","title":"chown 命令简介","tag":"201910","desc":""},"relativePath":"201910/20190826 Introduction to the Linux chown command.md","filePath":"[post].md"}'),r={name:"201910/20190826 Introduction to the Linux chown command.md"};function h(u,s,g,k,m,b){const a=p("Link");return d(),c("div",null,[s[20]||(s[20]=t(`<h1 id="chown-命令简介" tabindex="-1">chown 命令简介 <a class="header-anchor" href="#chown-命令简介" aria-label="Permalink to “chown 命令简介”">​</a></h1><blockquote><p>学习如何使用 chown 命令更改文件或目录的所有权。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201910/03/000014mfrxrxi5rej75mjs.jpg" alt=""></p><p>Linux 系统上的每个文件和目录均由某个人拥有，拥有者可以完全控制更改或删除他们拥有的文件。除了有一个<em>拥有用户</em>外，文件还有一个<em>拥有组</em>。</p><p>你可以使用 <code>ls -l</code> 命令查看文件的所有权：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[pablo@workstation Downloads]$ ls -l</span></span>
<span class="line"><span>total 2454732</span></span>
<span class="line"><span>-rw-r--r--. 1 pablo pablo 1934753792 Jul 25 18:49 Fedora-Workstation-Live-x86_64-30-1.2.iso</span></span></code></pre></div><p>该输出的第三和第四列是拥有用户和组，它们一起称为<em>所有权</em>。上面的那个 ISO 文件这两者都是 <code>pablo</code>。</p>`,7)),i("p",null,[s[1]||(s[1]=n("所有权设置由 ",-1)),e(a,{href:"https://opensource.com/article/19/8/introduction-linux-chmod-command"},{default:o(()=>[...s[0]||(s[0]=[n("chmod 命令",-1)])]),_:1}),s[2]||(s[2]=n("进行设置，控制允许谁可以执行读取、写入或运行的操作。你可以使用 ",-1)),s[3]||(s[3]=i("code",null,"chown",-1)),s[4]||(s[4]=n(" 命令更改所有权（一个或两者）。",-1))]),s[21]||(s[21]=t(`<p>所有权经常需要更改。文件和目录一直存在在系统中，但用户不断变来变去。当文件和目录在系统中移动时，或从一个系统移动到另一个系统时，所有权也可能需要更改。</p><p>我的主目录中的文件和目录的所有权是我的用户和我的主要组，以 <code>user:group</code> 的形式表示。假设 Susan 正在管理 Delta 组，该组需要编辑一个名为 <code>mynotes</code> 的文件。你可以使用 <code>chown</code> 命令将该文件的用户更改为 <code>susan</code>，组更改为 <code>delta</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown susan:delta mynotes</span></span>
<span class="line"><span>ls -l</span></span>
<span class="line"><span>-rw-rw-r--. 1 susan delta 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p>当给该文件设置好了 Delta 组时，它可以分配回给我：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown alan mynotes</span></span>
<span class="line"><span>$ ls -l mynotes</span></span>
<span class="line"><span>-rw-rw-r--. 1 alan delta 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p>给用户后添加冒号（<code>:</code>），可以将用户和组都分配回给我：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown alan: mynotes</span></span>
<span class="line"><span>$ ls -l mynotes</span></span>
<span class="line"><span>-rw-rw-r--. 1 alan alan 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p>通过在组前面加一个冒号，可以只更改组。现在，<code>gamma</code> 组的成员可以编辑该文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown :gamma mynotes</span></span>
<span class="line"><span>$ ls -l</span></span>
<span class="line"><span>-rw-rw-r--. 1 alan gamma 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p><code>chown</code> 的一些附加参数都能用在命令行和脚本中。就像许多其他 Linux 命令一样，<code>chown</code> 有一个递归参数（<code>-R</code>），它告诉该命令进入目录以对其中的所有文件进行操作。没有 <code>-R</code> 标志，你就只能更改文件夹的权限，而不会更改其中的文件。在此示例中，假定目的是更改目录及其所有内容的权限。这里我添加了 <code>-v</code>（详细）参数，以便 <code>chown</code> 报告其工作情况：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l . conf</span></span>
<span class="line"><span>.:</span></span>
<span class="line"><span>drwxrwxr-x 2 alan alan 4096 Aug  5 15:33 conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>conf:</span></span>
<span class="line"><span>-rw-rw-r-- 1 alan alan 0 Aug  5 15:33 conf.xml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ chown -vR susan:delta conf</span></span>
<span class="line"><span>changed ownership of &#39;conf/conf.xml&#39; from alan:alan to  susan:delta</span></span>
<span class="line"><span>changed ownership of &#39;conf&#39; from alan:alan to  susan:delta</span></span></code></pre></div><p>根据你的角色，你可能需要使用 <code>sudo</code> 来更改文件的所有权。</p><p>在更改文件的所有权以匹配特定配置时，或者在你不知道所有权时（例如运行脚本时），可以使用参考文件（<code>--reference=RFILE</code>）。例如，你可以复制另一个文件（<code>RFILE</code>，称为参考文件）的用户和组，以撤消上面所做的更改。回想一下，点（<code>.</code>）表示当前的工作目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown -vR --reference=. conf</span></span></code></pre></div><h3 id="报告更改" tabindex="-1">报告更改 <a class="header-anchor" href="#报告更改" aria-label="Permalink to “报告更改”">​</a></h3><p>大多数命令都有用于控制其输出的参数。最常见的是 <code>-v</code>（<code>--verbose</code>）以启用详细信息，但是 <code>chown</code> 还具有 <code>-c</code>（<code>--changes</code>）参数来指示 <code>chown</code> 仅在进行更改时报告。<code>chown</code> 还会报告其他情况，例如不允许进行的操作。</p><p>参数 <code>-f</code>（<code>--silent</code>、<code>--quiet</code>）用于禁止显示大多数错误消息。在下一节中，我将使用 <code>-f</code> 和 <code>-c</code>，以便仅显示实际更改。</p><h3 id="保持根目录" tabindex="-1">保持根目录 <a class="header-anchor" href="#保持根目录" aria-label="Permalink to “保持根目录”">​</a></h3><p>Linux 文件系统的根目录（<code>/</code>）应该受到高度重视。如果命令在此层级上犯了一个错误，则后果可能会使系统完全无用。尤其是在运行一个会递归修改甚至删除的命令时。<code>chown</code> 命令具有一个可用于保护和保持根目录的参数，它是 <code>--preserve-root</code>。如果在根目录中将此参数和递归一起使用，那么什么也不会发生，而是会出现一条消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown -cfR --preserve-root alan /</span></span>
<span class="line"><span>chown: it is dangerous to operate recursively on &#39;/&#39;</span></span>
<span class="line"><span>chown: use --no-preserve-root to override this failsafe</span></span></code></pre></div><p>如果不与 <code>--recursive</code> 结合使用，则该选项无效。但是，如果该命令由 <code>root</code> 用户运行，则 <code>/</code> 本身的权限将被更改，但其下的其他文件或目录的权限则不会更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown -c --preserve-root alan /</span></span>
<span class="line"><span>chown: changing ownership of &#39;/&#39;: Operation not permitted</span></span>
<span class="line"><span>[root@localhost /]# chown -c --preserve-root alan /</span></span>
<span class="line"><span>changed ownership of &#39;/&#39; from root to alan</span></span></code></pre></div><h3 id="所有权即安全" tabindex="-1">所有权即安全 <a class="header-anchor" href="#所有权即安全" aria-label="Permalink to “所有权即安全”">​</a></h3><p>文件和目录所有权是良好的信息安全性的一部分，因此，偶尔检查和维护文件所有权以防止不必要的访问非常重要。<code>chown</code> 命令是 Linux 安全命令集中最常见和最重要的命令之一。</p><hr>`,25)),i("p",null,[s[6]||(s[6]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/19/8/linux-chown-command"},{default:o(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/19/8/linux-chown-command",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/alanfdoss"},{default:o(()=>[...s[7]||(s[7]=[n("Alan Formy-Duval",-1)])]),_:1}),s[12]||(s[12]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 译者：",-1)),e(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[9]||(s[9]=[n("wxy",-1)])]),_:1}),s[14]||(s[14]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:o(()=>[...s[16]||(s[16]=[n("Linux中国",-1)])]),_:1}),s[19]||(s[19]=n(" 荣誉推出",-1))])])}const y=l(r,[["render",h]]);export{x as __pageData,y as default};
